-- Register rows the first import skipped because DoCA left the date cell blank or garbled: 291 approvals
-- from 2014, approvals 523 to 536 of 2024, and 6 others. Generated from scripts/fetch-model-approvals.mjs on 2 Oct 2026.
begin;
on conflict (year, cert_no, company, equipment) do nothing;
update public.model_approvals set fetched_at = '2026-10-02T02:27:32.217Z';
commit;

-- Demo case text: the dispenser limit is ±25 mL in a 5 L test (0.5 %), not ±25 mL per litre.
update public.enforcement_cases
   set data = replace(data::text, 'Spot check revealed fuel dispenser under-dispensing by 48mL per litre, exceeding MPE of ±25mL/L.',
                      'Spot check: the dispenser delivered 48 mL short in a 5 L test, beyond the ±25 mL (0.5 %) limit.')::jsonb
 where id = 'ENF-2026-0015';

-- LM-DL-2026-004011 was created in the 30 Sep test run with an approval mark that belongs to a steel tape
-- (IND/09/24/118, Industrial Tools Corporation). Use a real approval for this exact model class instead:
-- IND/09/25/49, M/s Jayan Electronics, brand JAYAN, series JET, class III, max 30 kg, e = 5 g.
-- None of these fields are in the signed QR payload, so the issued certificate still verifies.
update public.instruments set data = data || '{"manufacturer": "Jayan Electronics", "model": "JAYAN JET", "modelApprovalNumber": "IND/09/25/49"}'::jsonb
 where id = 'LM-DL-2026-004011';
update public.applications set data = replace(replace(replace(data::text, 'Sharda Steel Industries', 'Jayan Electronics'), 'IND/09/2024/118', 'IND/09/25/49'), '"SW-30"', '"JAYAN JET"')::jsonb
 where instrument_id = 'LM-DL-2026-004011';
update public.certificates set data = replace(replace(replace(data::text, 'Sharda Steel Industries', 'Jayan Electronics'), 'IND/09/2024/118', 'IND/09/25/49'), '"SW-30"', '"JAYAN JET"')::jsonb
 where instrument_id = 'LM-DL-2026-004011';

-- A demo notification quoted a compliance rate nobody computed. Point to the computed report instead.
update public.notifications
   set data = replace(data::text, 'Delhi jurisdiction: 87% compliance rate. 2 enforcement cases active, 1 compounding completed this month.',
                      'Delhi jurisdiction: weekly summary is ready. Open Reports for figures computed from the current records.')::jsonb
 where data::text like '%87% compliance rate%';

-- The demo "approval not in the register" case named a real company. Keep the case, use a fictional maker.
update public.instruments set data = replace(data::text, 'Sartorius India Pvt Ltd', 'Shakti Weighing Works (demo)')::jsonb where id = 'LM-DL-2026-002140';
update public.applications set data = replace(data::text, 'Sartorius India Pvt Ltd', 'Shakti Weighing Works (demo)')::jsonb where instrument_id = 'LM-DL-2026-002140';
update public.certificates set data = replace(data::text, 'Sartorius India Pvt Ltd', 'Shakti Weighing Works (demo)')::jsonb where instrument_id = 'LM-DL-2026-002140';

-- TULA is a prototype: no certificate names a government office as its issuer. Not part of the signed QR payload.
update public.certificates set data = replace(data::text, 'Controller of Legal Metrology, Delhi (demo)', 'Demo Delhi office (TULA prototype)')::jsonb
 where data::text like '%Controller of Legal Metrology, Delhi (demo)%';
update public.certificates set data = replace(data::text, 'Controller of Legal Metrology, Gujarat (demo)', 'Demo Gujarat office (TULA prototype)')::jsonb
 where data::text like '%Controller of Legal Metrology, Gujarat (demo)%';
update public.certificates set data = replace(data::text, '(Government Approved Test Centre)', '(demo test centre, TULA prototype)')::jsonb
 where data::text like '%(Government Approved Test Centre)%';
